1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	
28	const isKnownItemType = (item: Item): boolean =>
29	  item.type in BASE_PREMIUM_BY_ITEM_TYPE;
30	
31	const rejectUnknownItemTypes = (items: Item[]): void => {
32	  const unknown = items.find((item) => !isKnownItemType(item));
33	  if (unknown) {
34	    throw new Error(`Unknown item type: ${unknown.type}`);
35	  }
36	};
37	
38	const basePremiumOf = (item: Item): number =>
39	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
40	
41	const surchargeRateOf = (item: Item): number =>
42	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
43	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
44	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
45	    : 0);
46	
47	const surchargeOf = (item: Item): number =>
48	  basePremiumOf(item) * surchargeRateOf(item);
49	
50	const sumBasePremiums = (items: Item[]): number =>
51	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
52	
53	const sumItemSurcharges = (items: Item[]): number =>
54	  items.reduce((sum, item) => sum + surchargeOf(item), 0);
55	
56	// Policy-level modifiers are whole percentages of the policy base premium.
57	// Applying them as `amount * percent / 100` keeps the arithmetic exact:
58	// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
59	const applyPercentage = (amount: number, percent: number): number =>
60	  (amount * percent) / 100;
61	
62	const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
63	const LOYALTY_DISCOUNT_PERCENTAGE = 20;
64	const LOYALTY_YEARS_THRESHOLD = 2;
65	
66	const loyaltyDiscountPercentageOf = (customer: Customer): number =>
67	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
68	    ? LOYALTY_DISCOUNT_PERCENTAGE
69	    : 0;
70	
71	const FOLLOW_UP_DISCOUNT_PERCENTAGE = 15;
72	const FOLLOW_UP_CONTRACTS_THRESHOLD = 1;
73	
74	const followUpDiscountPercentageOf = (customer: Customer): number =>
75	  customer.previousContracts >= FOLLOW_UP_CONTRACTS_THRESHOLD
76	    ? FOLLOW_UP_DISCOUNT_PERCENTAGE
77	    : 0;
78	
79	const policyPercentageDeltaOf = (customer: Customer): number =>
80	  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
81	  loyaltyDiscountPercentageOf(customer) -
82	  followUpDiscountPercentageOf(customer);
83	
84	const BLOCK_SIZE = 3;
85	const BLOCK_BASE_PREMIUM = 60;
86	
87	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
88	  sameTypeGroup.length === BLOCK_SIZE;
89	
90	const groupByType = (items: Item[]): Item[][] => {
91	  const groups = new Map<string, Item[]>();
92	  for (const item of items) {
93	    const group = groups.get(item.type) ?? [];
94	    group.push(item);
95	    groups.set(item.type, group);
96	  }
97	  return [...groups.values()];
98	};
99	
100	const basePremiumOfGroup = (sameTypeGroup: Item[]): number =>
101	  isComponentBlock(sameTypeGroup)
102	    ? BLOCK_BASE_PREMIUM
103	    : sumBasePremiums(sameTypeGroup);
104	
105	const policyBasePremiumOf = (items: Item[]): number =>
106	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
107	
108	export const quote = (customer: Customer, items: Item[]): number => {
109	  rejectUnknownItemTypes(items);
110	
111	  const policyBasePremium = policyBasePremiumOf(items);
112	  const policyPercentageAdjustment = applyPercentage(
113	    policyBasePremium,
114	    policyPercentageDeltaOf(customer),
115	  );
116	
117	  return Math.ceil(
118	    policyBasePremium +
119	      sumItemSurcharges(items) +
120	      policyPercentageAdjustment +
121	      PROCESSING_FEE,
122	  );
123	};
124	
125	export type Damage = {
126	  itemType: string;
127	  amount: number;
128	};
129	
130	export type Incident = {
131	  cause: string;
132	  damages: Damage[];
133	};
134	
135	export type ClaimResult = {
136	  payout: number;
137	  remainingCap: number;
138	};
139	
140	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
141	  sword: 1000,
142	  amulet: 600,
143	};
144	
145	export const insuranceSum = (items: Item[]): number =>
146	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);
147	
148	export const claim = (
149	  _items: Item[],
150	  _incident: Incident,
151	  remainingCap: number,
152	): ClaimResult => ({ payout: remainingCap, remainingCap: 0 });
